package main

import (
	"errors"
	"os"
	"strings"
	"testing"
)

func TestForbidScan(t *testing.T) {
	rules, err := loadForbidRules("../../" + forbidWordsPath)
	if err != nil {
		t.Fatal(err)
	}
	marker := "TO" + "DO"
	skip := "t." + "Skip"
	files := map[string]string{
		"a.go":          "package a\n// " + marker + " fix\n",
		"b.go":          "package b\n// Code generated by x. DO NOT EDIT.\n// " + marker + "\n",
		"docs/x.go":     "// " + marker + "\n",
		"c_test.go":     "func TestX(t *testing.T) { " + skip + "(\"x\") }\n",
		"d.ts":          "const autodoToString = 1\n",
		"e.md":          marker + "\n",
		"tests/ui/a.ts": "test.o" + "nly('x')\n",
		"f.yaml":        "a: not " + "implemented\n",
		"g.go":          "var StatusNotImplemented = 1 // x\n",
	}
	read := func(p string) ([]byte, error) {
		s, ok := files[p]
		if !ok {
			return nil, os.ErrNotExist
		}
		return []byte(s), nil
	}
	var list []string
	for k := range files {
		list = append(list, k)
	}
	found, err := scanForbid(list, rules, read)
	if err != nil {
		t.Fatal(err)
	}
	got := map[string]bool{}
	for _, f := range found {
		got[f.Path] = true
	}
	for _, want := range []string{"a.go", "c_test.go", "tests/ui/a.ts", "f.yaml"} {
		if !got[want] {
			t.Errorf("expected finding in %s", want)
		}
	}
	for _, not := range []string{"b.go", "docs/x.go", "d.ts", "e.md", "g.go"} {
		if got[not] {
			t.Errorf("unexpected finding in %s", not)
		}
	}
}

const sddFixture = `
| REQ-CORE-001 | x |
| REQ-CORE-002 | y |
| SI-01 | z |

- **SCN-CORE-001** [E] (REQ-CORE-001, SI-01) text.
- **SCN-CORE-002** [I] (REQ-CORE-002) text.
`

func fixtureSDD(t *testing.T) *SDD {
	t.Helper()
	dir := t.TempDir()
	wd, _ := os.Getwd()
	t.Cleanup(func() { _ = os.Chdir(wd) })
	_ = os.MkdirAll(dir+"/docs", 0o755)
	_ = os.WriteFile(dir+"/"+sddPath, []byte(sddFixture), 0o644)
	if err := os.Chdir(dir); err != nil {
		t.Fatal(err)
	}
	s, err := loadSDD()
	if err != nil {
		t.Fatal(err)
	}
	return s
}

func TestTraceRules(t *testing.T) {
	s := fixtureSDD(t)
	res := computeTrace(s, []TestCase{
		{Name: "TestSCN_CORE_001_A", Status: "passed"},
		{Name: "SCN-CORE-002 ui", Status: "skipped"},
		{Name: "TestSCN_CORE_009_Unknown", Status: "passed"},
	})
	joined := strings.Join(res.Errors, "\n")
	if res.OK || !strings.Contains(joined, "rule 3: SCN-CORE-002") || !strings.Contains(joined, "rule 4") {
		t.Fatalf("errors: %s", joined)
	}
	res = computeTrace(s, []TestCase{
		{Name: "TestSCN_CORE_001_A", Status: "passed"},
		{Name: "SCN-CORE-002 ui", Status: "passed"},
		{Classname: "github.com/x/tests/review/round-1", Name: "TestF_1_1", Status: "passed"},
	})
	if !res.OK {
		t.Fatalf("errors: %v", res.Errors)
	}
}

func TestLedgerRules(t *testing.T) {
	s := fixtureSDD(t)
	ledger := func(status, rows string) *Ledger {
		src := "# L\n\nstatus: " + status + "\nsdd_sha256: " + s.Hash + "\ncurrent_slice: S0\nreview_round: 0\nreview_complete: false\nblocking_findings_open: 0\n\n## Blocked\n\n## Items\n\n| ID | Status | Slice | Evidence |\n|---|---|---|---|\n" + rows
		l, err := parseLedger(src)
		if err != nil {
			t.Fatal(err)
		}
		return l
	}
	read := func(p string) ([]byte, error) {
		if p == "x_test.go" {
			return []byte("func TestSCN_CORE_001_A(t *testing.T) {}"), nil
		}
		return nil, errors.New("missing")
	}
	good := "| REQ-CORE-001 | PASS | S0 | SCN-CORE-001 |\n| REQ-CORE-002 | OPEN | S0 | |\n| SI-01 | OPEN | S0 | |\n| SCN-CORE-001 | PASS | S0 | x_test.go::TestSCN_CORE_001_A |\n| SCN-CORE-002 | OPEN | S0 | |\n"
	if errs := checkLedger(ledger("IN_PROGRESS", good), s, read); len(errs) != 0 {
		t.Fatalf("good ledger: %v", errs)
	}
	bad := "| REQ-CORE-001 | PASS | S0 | |\n| REQ-CORE-002 | PASS | S0 | |\n| SCN-CORE-001 | PASS | S0 | y_test.go::TestSCN_CORE_001_A |\n| SCN-CORE-002 | OPEN | S0 | |\n| SCN-CORE-002 | OPEN | S0 | |\n"
	errs := strings.Join(checkLedger(ledger("DONE", bad), s, read), "\n")
	for _, want := range []string{"rule 2: SI-01 appears 0", "rule 2: SCN-CORE-002 appears 2", "rule 3: SCN-CORE-001", "rule 4: REQ-CORE-002", "rule 5"} {
		if !strings.Contains(errs, want) {
			t.Errorf("missing %q in:\n%s", want, errs)
		}
	}
}
